mapper.select:
select * from ( SELECT vts.*, vtu.nickname, vtt.taste_type,
( SELECT type_name FROM vote_taste_score WHERE vote_taste_score.taste_type_id = #{its.id} AND open_id = vts.open_id LIMIT 1 ) field#{its.id}, ( SELECT judge_result FROM vote_taste_score WHERE vote_taste_score.taste_type_id = #{its.id} AND open_id = vts.open_id LIMIT 1 ) judge_result#{its.id}, ( SELECT vote_taste_score.score FROM vote_taste_score WHERE vote_taste_score.taste_type_id = #{its.id} AND vote_taste_score.open_id = vts.open_id LIMIT 1 ) score#{its.id}
FROM (SELECT * FROM vote_taste_score WHERE vote_taste_score.taste_id = #{tasteId}) vts LEFT JOIN vote_taste_user vtu ON vtu.openid = vts.open_id LEFT JOIN vote_taste_type vtt ON vtt.id = vts.taste_type_id GROUP BY vts.open_id ) a LIMIT #{pageIndex}, #{pageSize}

select count(0) from ( SELECT vts.*, vtu.nickname, vtt.taste_type,
( SELECT type_name FROM vote_taste_score WHERE vote_taste_score.taste_type_id = #{its.id} AND open_id = vts.open_id LIMIT 1 ) field#{its.id}, ( SELECT vote_taste_score.score FROM vote_taste_score WHERE vote_taste_score.taste_type_id = #{its.id} AND vote_taste_score.open_id = vts.open_id LIMIT 1 ) score#{its.id}
FROM (SELECT * FROM vote_taste_score WHERE vote_taste_score.taste_id = #{tasteId}) vts LEFT JOIN vote_taste_user vtu ON vtu.openid = vts.open_id LEFT JOIN vote_taste_type vtt ON vtt.id = vts.taste_type_id GROUP BY vts.open_id ) a
